import { readFileSync, writeFileSync } from 'node:fs';

/**
 * Copies the canonical root README.md into the published package, prefixed with an
 * HTML comment so anyone opening the package copy's source sees it is generated.
 * The comment is invisible in the rendered README on GitHub and npm.
 */
const banner = [
  '<!--',
  '  AUTOGENERATED - DO NOT EDIT.',
  '  This file is a copy of the repository root README.md, written by `npm run sync:readme` (which runs as part of `npm run build`).',
  '  Edit the root README.md instead; any changes made here will be overwritten on the next build.',
  '-->',
  '',
  '',
].join('\n');

writeFileSync('projects/signalkin/README.md', banner + readFileSync('README.md', 'utf8'));
